import React from "react";
import Inline from "../Inline";
import Link from "./Link";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Link> = {
  id: "Components/Link",
  title: "Components/Link",
  component: Link,
  argTypes: {
    title: { type: "string", control: "text" },
    href: { type: "string", control: "text" },
    inline:{ type: "boolean", control: "boolean", description: "Apply inline link styling (to be used in paragraphs)"   },
    negative: { control: false, description: "Apply negative on dark backgrounds." },
    disabled: { type: "boolean", control: "boolean" },
    size: {
      options: ["xsmall", "small", "medium", "large"],
      control: { type: "select" },
      table: {
        defaultValue: { summary: "medium" },  // Default value for size
      }
    },
  }
};

export default meta;
type Story = StoryObj<typeof Link>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    title: "title",
    href: "#",
  },
  render: (args) => (
    <Inline spacing="2-x">
      <Link {...args} onClick={(e) => e.preventDefault()}>
        Default
      </Link>
    </Inline>
  ),
};

export const Negative: Story = {
  tags: ["visual-test"],
  args: {
    title: "title",
    href: "#",
  },
  render: (args) => (
    <Inline spacing="2-x" padding="2-x" className="bg-primaryblue-90">
      <Link {...args} onClick={(e) => e.preventDefault()} negative>
        Default
      </Link>
    </Inline>
  ),
};

export const Disabled: Story = {
  args: {
    disabled: true,
  },
  render: (args) => (
    <Inline spacing="2-x">
      <Link
        {...args}
        title="title"
        href="#"
        onClick={(e) => e.preventDefault()}
      >
        Default
      </Link>
    </Inline>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Inline spacing="2-x">
      <Link title="title" href="#" onClick={(e) => e.preventDefault()}>
        Default
      </Link>
    </Inline>
  ),
};

